## 第 7 步：芯片层从 FIFO 取样本

`bk7258_aud.c:1152`

```c
unsigned int bk7258_aud_adc_read(int16_t *samples, unsigned int nsamples)
{
  unsigned int read = 0;
  unsigned int step;
  uint32_t word;

  /* 一个 FIFO 字里 L 在 [15:0]、R 在 [31:16]。开了回声参考（MIC2）时两半都要，
   * 调用者看到的是 L,R 交错；否则只存 L。*/

  step = g_aud_capture_reference ? 2 : 1;

  while (read + step <= nsamples)
    {
      if ((getreg32(BK7258_AUD_FIFO_STATUS) &
           BK7258_AUD_ADC_FIFO_EMPTY) != 0)
        {
          break;                        /* FIFO 空了就停，返回实际读到的数量 —— 
                                         * 上层靠"要的比给的多"判断该等下次中断 */
        }

      word = getreg32(BK7258_AUD_ADC_FIFO_PORT);   /* 读一次弹出一个字 */

      samples[read++] = (int16_t)((word >> BK7258_AUD_FIFO_L_SHIFT) &
                                 BK7258_AUD_FIFO_SAMPLE_MASK);

      if (step == 2)
        {
          samples[read++] = (int16_t)((word >> BK7258_AUD_FIFO_R_SHIFT) &
                                      BK7258_AUD_FIFO_SAMPLE_MASK);
        }
    }

  return read;
}
```

<callout emoji="zap" background-color="pale-gray" border-color="light-gray">
**这是整条链上唯一真正接触样本数据的地方。** 上面所有层都在传指针和长度，只有这里做 `getreg32` 把数据从硬件搬进内存。
</callout>

---

## 第 8 步：缓冲回流（中断 → 线程）

缓冲装满后不能在中断里直接通知应用，因为那会走消息队列、可能唤醒线程：

```c
/* :246  中断上下文：只挪队列 + 派一个工作项，立刻返回 */
static void bk7258_audio_finish(FAR struct bk7258_audio_s *priv,
                                FAR struct ap_buffer_s *apb)
{
  dq_addlast(&apb->dq_entry, &priv->doneq);

  if (work_available(&priv->work))      /* 已经派过就不重复派 */
    {
      work_queue(HPWORK, &priv->work, bk7258_audio_complete_work, priv, 0);
    }
}

/* :211  线程上下文（HPWORK）：真正通知上半部 */
static void bk7258_audio_complete_work(FAR void *arg)
{
  FAR struct bk7258_audio_s *priv = arg;

  for (; ; )
    {
      flags = enter_critical_section();
      apb = (FAR struct ap_buffer_s *)dq_remfirst(&priv->doneq);
      leave_critical_section(flags);
      /* ↑ doneq 会被中断修改，取的时候必须关中断 */

      if (apb == NULL)
        {
          break;                        /* 排空为止，一次工作项处理完所有积压 */
        }

      priv->dev.upper(priv->dev.priv, AUDIO_CALLBACK_DEQUEUE, apb, OK);
      /* ★ 上行回调。这个 upper 函数指针是 audio_register() 时上半部填好的，
       *   和 ops 表方向相反：ops 是"上半部调我"，upper 是"我调上半部" */
    }
}
```

